import httpx
from sqlalchemy.orm import Session as DBSession

from app.agent.prompts import SYSTEM_PROMPT
from app.agent.providers.base import AgentResult
from app.agent.tools import grounded_qa_query
from app.core.config import get_settings

settings = get_settings()

# Verified live against Ollama 0.13.4 / llama3.2:3b: /api/chat accepts an
# OpenAI-style `tools` array and returns message.tool_calls with parsed
# (not string) arguments; a role:"tool" message with tool_call_id continues
# the loop and produces a normal text reply. No SDK for this — raw HTTP,
# matching how ingestion's embeddings.py already talks to Ollama.
#
# gemma3:4b and phi3:3.8b were also tested and both hard-error
# ("does not support tools") rather than just being less reliable — see
# architecture.md §6. OLLAMA_CHAT_MODEL must be a model that supports tools.
GROUNDED_QA_SCHEMA = {
    "type": "function",
    "function": {
        "name": "grounded_qa",
        "description": "Answer product/growth questions using Lenny's Podcast transcripts.",
        "parameters": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": (
                        "A self-contained question to search the transcript knowledge "
                        "base for. Incorporate relevant context from the conversation "
                        "so far — this tool has no memory of prior turns."
                    ),
                }
            },
            "required": ["query"],
        },
    },
}

MAX_TOOL_ITERATIONS = 4


class OllamaChatError(Exception):
    """Raised when the local Ollama chat call fails. Distinct from
    ingestion.embeddings.EmbeddingError per architecture.md §8 — chat-Ollama-down
    and embedding-Ollama-down are different failure modes needing different
    error_codes once Phase 7 registers handlers for both."""


def run(db: DBSession, messages: list[dict]) -> AgentResult:
    captured_citations: list[dict] = []
    chat_messages = [{"role": "system", "content": SYSTEM_PROMPT}, *messages]

    for _ in range(MAX_TOOL_ITERATIONS):
        try:
            response = httpx.post(
                f"{settings.ollama_host}/api/chat",
                json={
                    "model": settings.ollama_chat_model,
                    "messages": chat_messages,
                    "tools": [GROUNDED_QA_SCHEMA],
                    "stream": False,
                },
                timeout=120.0,
            )
            response.raise_for_status()
        except httpx.HTTPError as exc:
            raise OllamaChatError(
                f"Ollama chat call failed (host={settings.ollama_host}): {exc}"
            ) from exc

        message = response.json()["message"]
        tool_calls = message.get("tool_calls") or []

        if not tool_calls:
            return AgentResult(content=message.get("content", ""), citations=captured_citations)

        chat_messages.append(message)
        for call in tool_calls:
            if call["function"]["name"] == "grounded_qa":
                result_text = grounded_qa_query(
                    db, call["function"]["arguments"]["query"], captured_citations
                )
            else:
                result_text = f"Unknown tool: {call['function']['name']}"
            chat_messages.append(
                {"role": "tool", "content": result_text, "tool_call_id": call.get("id", "")}
            )

    return AgentResult(
        content="I wasn't able to finish answering within the allotted tool-call budget.",
        citations=captured_citations,
    )

from sqlalchemy.orm import Session as DBSession

from app.agent.retrieval import RetrievedChunk, retrieve

NOT_COVERED_MESSAGE = (
    "No relevant material was found in the available transcripts for this query. "
    "Tell the user explicitly that this isn't covered in the source material, "
    "rather than answering from general knowledge."
)


def _format_context(chunks: list[RetrievedChunk]) -> str:
    if not chunks:
        return NOT_COVERED_MESSAGE
    return "\n\n---\n\n".join(
        f"[Source: {c.episode_title}, at {c.start_timestamp}]\n{c.chunk_text}" for c in chunks
    )


def _chunks_to_citations(chunks: list[RetrievedChunk]) -> list[dict]:
    return [
        {
            "episode_title": c.episode_title,
            "episode_source_url": c.episode_source_url,
            "start_timestamp": c.start_timestamp,
            "chunk_id": c.chunk_id,
        }
        for c in chunks
    ]


def grounded_qa_query(db: DBSession, query: str, captured_citations: list[dict]) -> str:
    """Shared retrieval logic behind the grounded_qa tool for both providers.

    Tool results are plain text on both Claude's Tool Runner and Ollama's
    /api/chat, so structured citation data can't travel back through the
    tool-calling mechanism itself. `captured_citations` is a mutable list
    the caller (each provider module) reads after the agent loop finishes,
    to attach as the persisted Message's `citations` field.
    """
    chunks = retrieve(db, query)
    captured_citations.extend(_chunks_to_citations(chunks))
    return _format_context(chunks)

